// 42-tap DIRECT-FORM FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path -> lower Fmax; pipeline it to go faster).
module firr42_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:41];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd2 * xs[0] + 8'd5 + 8'd4 * xs[1] + 8'd7 * xs[2] + 8'd10 * xs[3] + 8'd13 * xs[4] + 8'd16 * xs[5] + 8'd19 * xs[6] + 8'd22 * xs[7] + 8'd25 * xs[8] + 8'd28 * xs[9] + 8'd31 * xs[10] + 8'd34 * xs[11] + 8'd37 * xs[12] + 8'd40 * xs[13] + 8'd43 * xs[14] + 8'd46 * xs[15] + 8'd49 * xs[16] + 8'd52 * xs[17] + 8'd55 * xs[18] + 8'd58 * xs[19] + 8'd61 * xs[20] + 8'd64 * xs[21] + 8'd67 * xs[22] + 8'd70 * xs[23] + 8'd73 * xs[24] + 8'd76 * xs[25] + 8'd79 * xs[26] + 8'd82 * xs[27] + 8'd85 * xs[28] + 8'd88 * xs[29] + 8'd91 * xs[30] + 8'd94 * xs[31] + 8'd97 * xs[32] + 8'd100 * xs[33] + 8'd103 * xs[34] + 8'd106 * xs[35] + 8'd109 * xs[36] + 8'd112 * xs[37] + 8'd115 * xs[38] + 8'd118 * xs[39] + 8'd121 * xs[40] + 8'd124 * xs[41];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 42; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 42; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
